import { mapState } from "vuex";
export default {
  name: "picture_cube",
  cname: "图片魔方",
  configName: "c_picture_cube",
  icon: "#iconzujian-tupianmofang",
  type: 0, // 0 基础组件 1 营销组件 2工具组件
  defaultName: "pictureCube", // 外面匹配名称
  props: {
    index: {
      type: null,
    },
    num: {
      type: null,
    },
  },
  computed: {
    ...mapState("admin/mobildConfig", ["defaultArray"]),
  },
  watch: {
    pageData: {
      handler(nVal) {
        this.setConfig(nVal);
      },
      deep: true,
    },
    num: {
      handler(nVal) {
        let data = this.$store.state.admin.mobildConfig.defaultArray[nVal];
        this.setConfig(data);
      },
      deep: true,
    },
    defaultArray: {
      handler() {
        let data = this.$store.state.admin.mobildConfig.defaultArray[this.num];
        this.setConfig(data);
      },
      deep: true,
    },
  },
  data() {
    return {
      // 默认初始化数据禁止修改
      defaultConfig: {
        cname: "图片魔方",
        name: "pictureCube",
        timestamp: this.num,
		isHide:false,
        setUp: {
          tabVal: 0,
        },
        titleLeft: "展示设置",
        titleShow: "展示设置",
        titleContent: "内容设置",
        titleRight: "图片魔方",
        titleCurrency: "通用样式",
        styleConfig: {
          title: "选择风格",
          tabVal: 0,
          count: 2,
          type: "pictureCube",
        },
        picStyle: {
          tabVal: 0,
          picList: [],
          docPicList: [],
        },

        menuConfig: {
          title: "",
          maxList: 1,
          isCube: 1,
          list: [
            {
              img: "",
              info: [
                {
                  title: "链接",
                  tips: "请输入链接",
                  value: "",
                  max: 100,
                },
              ],
            },
          ],
        },
        imgConfig: {
          title: "图片间距",
          val: 0,
          min: 0,
        },
        filletImg: {
          title: "图片圆角",
          type: 0,
          list: [
            {
              val: "全部",
              icon: "iconDot",
            },
            {
              val: "单个",
              icon: "iconSquarepoint",
            },
          ],
          valName: "圆角值",
          val: 0,
          min: 0,
          valList: [{ val: 0 }, { val: 0 }, { val: 0 }, { val: 0 }],
        },
        bottomBgColor: {
          title: "底部背景",
          default: [
            {
              item: "#f5f5f5",
            },
          ],
          color: [
            {
              item: "#f5f5f5",
            },
          ],
        },
        topConfig: {
          title: "上边距",
          val: 0,
          min: 0,
        },
        bottomConfig: {
          title: "下边距",
          val: 0,
          min: 0,
        },
        prConfig: {
          title: "左右边距",
          val: 0,
          min: 0,
        },
        mbConfig: {
          title: "页面上间距",
          val: 0,
          min: 0,
        },
      },
      pageData: {},
      style: 0,
      picList: [],
      docPicList: [],
      bottomBgColor: [],
      mTop: 0,
      topConfig: 0,
      bottomConfig: 0,
      prConfig: 0,
      imgRadius: 0,
      imgConfig: 0,
    };
  },
  mounted() {
    this.$nextTick(() => {
      this.pageData =
        this.$store.state.admin.mobildConfig.defaultArray[this.num];
      this.setConfig(this.pageData);
    });
  },
  methods: {
    setConfig(data) {
      if (!data) return;
      if (data.mbConfig) {
        this.style = data.styleConfig.tabVal;
        this.bottomBgColor = data.bottomBgColor.color[0].item;
        this.prConfig = data.prConfig.val;
        this.mTop = data.mbConfig.val;
        this.topConfig = data.topConfig.val;
        this.bottomConfig = data.bottomConfig.val;
        let filletImg = data.filletImg.type;
        let filletValImg = data.filletImg.val;
        let valListImg = data.filletImg.valList;
        this.imgRadius = filletImg
          ? valListImg[0].val +
            "px " +
            valListImg[1].val +
            "px " +
            valListImg[3].val +
            "px " +
            valListImg[2].val +
            "px"
          : filletValImg + "px";
        this.imgConfig = data.imgConfig.val;
        if (data.styleConfig.tabVal !== 11) {
          if (!data.picStyle.picList.length) {
            this.picList = [
              {
                image: "",
                link: "",
              },
            ];
          } else {
            this.picList = data.picStyle.picList;
          }
        } else {
          data.picStyle.docPicList.map((e, i) => {
            data.picStyle.docPicList[i].img = data.picStyle.picList[i].image;
            data.picStyle.docPicList[i].link = data.picStyle.picList[i].link;
          });
          this.$set(this, "docPicList", data.picStyle.docPicList);
        }
      }
    },
  },
};
